function wrap(x,y,text,width=18,size=15,color='#355b72'){let s='';const str=String(text);for(let i=0;i<str.length;i+=width)s+=label(x,y+Math.floor(i/width)*(size+7),str.slice(i,i+width),size,color);return s;}
